import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { ChatMessage } from '../types';

const ChatBotView: React.FC = () => {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [isDeepThink, setIsDeepThink] = useState(false);
  const [isSearching, setIsSearching] = useState(false);
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping]);

  const handleSend = async () => {
    if (!input.trim() || isTyping) return;

    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', text: input };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsTyping(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const modelName = 'gemini-3-pro-preview';

      const config: any = {};
      if (isDeepThink) {
        config.thinkingConfig = { thinkingBudget: 32768 };
      }
      if (isSearching) {
        config.tools = [{ googleSearch: {} }];
      }

      const chat = ai.chats.create({
        model: modelName,
        config: {
          systemInstruction: "You are a highly capable AI assistant. Be concise but thorough.",
          ...config
        },
      });

      const result = await chat.sendMessageStream({ message: input });

      let aiMsg: ChatMessage = { id: (Date.now() + 1).toString(), role: 'model', text: '' };
      setMessages(prev => [...prev, aiMsg]);

      for await (const chunk of result) {
        const c = chunk as GenerateContentResponse;
        const text = c.text || "";

        // Extract grounding if available
        const chunks = c.candidates?.[0]?.groundingMetadata?.groundingChunks;
        const urls = chunks?.map((gc: any) => ({
          title: gc.web?.title || 'Source',
          uri: gc.web?.uri || '#'
        })).filter((u: any) => u.uri !== '#');

        setMessages(prev => prev.map(m => 
          m.id === aiMsg.id 
            ? { ...m, text: m.text + text, groundingUrls: urls?.length ? urls : m.groundingUrls } 
            : m
        ));
      }
    } catch (error) {
      console.error("Chat error:", error);
      setMessages(prev => [...prev, { 
        id: Date.now().toString(), 
        role: 'model', 
        text: "I'm sorry, I encountered an error. Please check your connection and try again." 
      }]);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="flex flex-col h-full gap-4">
      <header className="flex flex-col gap-2">
        <h2 className="text-2xl font-bold">Intelligent Chat</h2>
        <p className="text-slate-400">Powered by Gemini 3 Pro with multi-modal capabilities.</p>

        <div className="flex gap-4 mt-2">
          <label className="flex items-center gap-2 cursor-pointer bg-slate-800/50 px-3 py-1.5 rounded-lg border border-slate-700 hover:border-indigo-500 transition-colors">
            <input 
              type="checkbox" 
              checked={isDeepThink} 
              onChange={(e) => setIsDeepThink(e.target.checked)}
              className="w-4 h-4 accent-indigo-500"
            />
            <span className="text-sm font-medium">Deep Think (32k Budget)</span>
          </label>
          <label className="flex items-center gap-2 cursor-pointer bg-slate-800/50 px-3 py-1.5 rounded-lg border border-slate-700 hover:border-indigo-500 transition-colors">
            <input 
              type="checkbox" 
              checked={isSearching} 
              onChange={(e) => setIsSearching(e.target.checked)}
              className="w-4 h-4 accent-indigo-500"
            />
            <span className="text-sm font-medium">Google Search</span>
          </label>
        </div>
      </header>

      <div 
        ref={scrollRef}
        className="flex-1 overflow-y-auto space-y-4 p-4 glass-panel rounded-2xl min-h-[400px]"
      >
        {messages.length === 0 && (
          <div className="h-full flex flex-col items-center justify-center text-slate-500 gap-4 opacity-50">
            <div className="text-6xl">💬</div>
            <p>Start a conversation. Try "Explain quantum physics" or "Recent news about Mars".</p>
          </div>
        )}
        {messages.map((m) => (
          <div key={m.id} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] rounded-2xl px-4 py-3 ${
              m.role === 'user' 
                ? 'bg-indigo-600 text-white shadow-md' 
                : 'bg-slate-800 text-slate-100 border border-slate-700'
            }`}>
              <div className="whitespace-pre-wrap leading-relaxed">{m.text}</div>
              {m.groundingUrls && m.groundingUrls.length > 0 && (
                <div className="mt-3 pt-3 border-t border-slate-700 flex flex-wrap gap-2">
                  <span className="text-xs text-slate-500 block w-full mb-1">Sources:</span>
                  {m.groundingUrls.map((url, idx) => (
                    <a 
                      key={idx} 
                      href={url.uri} 
                      target="_blank" 
                      rel="noopener noreferrer"
                      className="text-xs bg-indigo-900/40 text-indigo-300 px-2 py-1 rounded border border-indigo-700 hover:bg-indigo-800 transition-colors"
                    >
                      {url.title}
                    </a>
                  ))}
                </div>
              )}
            </div>
          </div>
        ))}
        {isTyping && (
          <div className="flex justify-start">
            <div className="bg-slate-800 rounded-2xl px-4 py-3 border border-slate-700 animate-pulse">
              Generating...
            </div>
          </div>
        )}
      </div>

      <div className="flex gap-2 p-2 bg-slate-900 rounded-2xl border border-slate-800 focus-within:border-indigo-500 transition-all">
        <input 
          type="text" 
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyDown={(e) => e.key === 'Enter' && handleSend()}
          placeholder="Ask anything..."
          className="flex-1 bg-transparent border-none focus:ring-0 px-4 py-2"
        />
        <button 
          onClick={handleSend}
          disabled={isTyping}
          className="bg-indigo-600 hover:bg-indigo-500 disabled:opacity-50 text-white px-6 py-2 rounded-xl font-bold transition-all shadow-lg active:scale-95"
        >
          Send
        </button>
      </div>
    </div>
  );
};

export default ChatBotView;

import React, { useState, useEffect, useRef } from 'react';
import { GoogleGenAI, Modality } from '@google/genai';
import { decode, encode, decodeAudioData } from '../utils/audio';

const VoiceAssistantView: React.FC = () => {
  const [isActive, setIsActive] = useState(false);
  const [isConnecting, setIsConnecting] = useState(false);
  const [transcript, setTranscript] = useState<string[]>([]);

  const audioContextRef = useRef<AudioContext | null>(null);
  const sessionRef = useRef<any>(null);
  const nextStartTimeRef = useRef<number>(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());

  const startSession = async () => {
    setIsConnecting(true);
    setTranscript([]);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });

      const inputAudioContext = new AudioContext({ sampleRate: 16000 });
      const outputAudioContext = new AudioContext({ sampleRate: 24000 });
      audioContextRef.current = outputAudioContext;

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            setIsActive(true);
            setIsConnecting(false);

            // Microphone input processing
            const source = inputAudioContext.createMediaStreamSource(stream);
            const scriptProcessor = inputAudioContext.createScriptProcessor(4096, 1, 1);

            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const l = inputData.length;
              const int16 = new Int16Array(l);
              for (let i = 0; i < l; i++) {
                int16[i] = inputData[i] * 32768;
              }
              const pcmBlob = {
                data: encode(new Uint8Array(int16.buffer)),
                mimeType: 'audio/pcm;rate=16000',
              };

              sessionPromise.then((session) => {
                session.sendRealtimeInput({ media: pcmBlob });
              });
            };

            source.connect(scriptProcessor);
            scriptProcessor.connect(inputAudioContext.destination);
          },
          onmessage: async (message: any) => {
            // Handle transcriptions
            if (message.serverContent?.outputTranscription) {
              const text = message.serverContent.outputTranscription.text;
              setTranscript(prev => [...prev.slice(0, -1), (prev[prev.length - 1] || '') + text]);
            } else if (message.serverContent?.inputTranscription) {
              const text = message.serverContent.inputTranscription.text;
              setTranscript(prev => [...prev, `You: ${text}`]);
            }
            if (message.serverContent?.turnComplete) {
              setTranscript(prev => [...prev, ""]);
            }

            // Handle audio output
            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio) {
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputAudioContext.currentTime);
              const audioBuffer = await decodeAudioData(decode(base64Audio), outputAudioContext, 24000, 1);
              const source = outputAudioContext.createBufferSource();
              source.buffer = audioBuffer;
              source.connect(outputAudioContext.destination);
              source.addEventListener('ended', () => sourcesRef.current.delete(source));
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += audioBuffer.duration;
              sourcesRef.current.add(source);
            }

            if (message.serverContent?.interrupted) {
              sourcesRef.current.forEach(s => s.stop());
              sourcesRef.current.clear();
              nextStartTimeRef.current = 0;
            }
          },
          onerror: (e) => console.error('Live API Error:', e),
          onclose: () => stopSession(),
        },
        config: {
          responseModalities: [Modality.AUDIO],
          outputAudioTranscription: {},
          inputAudioTranscription: {},
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Zephyr' } },
          },
          systemInstruction: 'You are a helpful and fast voice assistant. Keep responses naturally short for a spoken conversation.'
        },
      });

      sessionRef.current = await sessionPromise;
    } catch (err) {
      console.error('Failed to start session:', err);
      setIsConnecting(false);
    }
  };

  const stopSession = () => {
    if (sessionRef.current) {
      sessionRef.current.close();
      sessionRef.current = null;
    }
    setIsActive(false);
    setIsConnecting(false);
  };

  return (
    <div className="flex flex-col h-full gap-6">
      <header>
        <h2 className="text-2xl font-bold">Live Voice Assistant</h2>
        <p className="text-slate-400">Low-latency conversational experience powered by Gemini 2.5 Native Audio.</p>
      </header>

      <div className="flex-1 glass-panel rounded-3xl p-12 flex flex-col items-center justify-center relative overflow-hidden">
        <div className={`w-48 h-48 rounded-full flex items-center justify-center transition-all duration-500 relative ${
          isActive ? 'bg-indigo-600/20' : 'bg-slate-800'
        }`}>
          {/* Pulsing rings for active state */}
          {isActive && (
            <>
              <div className="absolute inset-0 rounded-full border-4 border-indigo-500/50 animate-ping" />
              <div className="absolute inset-4 rounded-full border-4 border-indigo-400/30 animate-[ping_2s_linear_infinite]" />
            </>
          )}

          <button
            onClick={isActive ? stopSession : startSession}
            disabled={isConnecting}
            className={`w-32 h-32 rounded-full flex items-center justify-center text-4xl transition-all shadow-2xl z-10 ${
              isActive 
                ? 'bg-red-500 hover:bg-red-600 scale-110' 
                : 'bg-indigo-600 hover:bg-indigo-500 hover:scale-105'
            } disabled:opacity-50`}
          >
            {isConnecting ? '⏳' : isActive ? '⏹️' : '🎙️'}
          </button>
        </div>

        <div className="mt-12 text-center">
          <p className="text-xl font-medium">
            {isConnecting ? 'Establishing connection...' : isActive ? 'Listening...' : 'Ready to talk'}
          </p>
          <p className="text-slate-500 text-sm mt-2">
            {isActive ? 'Click to stop the conversation' : 'Click the microphone to start'}
          </p>
        </div>

        {/* Real-time Transcription Display */}
        {isActive && transcript.length > 0 && (
          <div className="absolute bottom-8 left-8 right-8 bg-slate-900/80 backdrop-blur rounded-xl p-4 border border-slate-700 max-h-32 overflow-y-auto">
            {transcript.map((line, i) => (
              <p key={i} className="text-sm text-slate-300">{line}</p>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default VoiceAssistantView;

import React, { useState } from 'react';
import { GoogleGenAI } from "@google/genai";

const ImageEditorView: React.FC = () => {
  const [originalImage, setOriginalImage] = useState<string | null>(null);
  const [editedImage, setEditedImage] = useState<string | null>(null);
  const [prompt, setPrompt] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (ev) => {
        setOriginalImage(ev.target?.result as string);
        setEditedImage(null);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleEdit = async () => {
    if (!originalImage || !prompt.trim()) return;
    setIsProcessing(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const base64Data = originalImage.split(',')[1];
      const mimeType = originalImage.split(',')[0].split(':')[1].split(';')[0];

      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash-image',
        contents: {
          parts: [
            { inlineData: { data: base64Data, mimeType } },
            { text: prompt }
          ],
        },
      });

      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData) {
          setEditedImage(`data:${mimeType};base64,${part.inlineData.data}`);
        }
      }
    } catch (error) {
      console.error('Image edit failed:', error);
      alert('Failed to edit image. Ensure you are using a supported image type.');
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <div className="flex flex-col h-full gap-6">
      <header>
        <h2 className="text-2xl font-bold text-white">GenAI Image Editor</h2>
        <p className="text-slate-400">Describe changes to your image using Gemini 2.5 Flash Image.</p>
      </header>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 flex-1 min-h-0">
        <div className="glass-panel rounded-2xl p-4 flex flex-col gap-4 overflow-hidden">
          <h3 className="text-sm font-semibold uppercase tracking-wider text-slate-500">Source Image</h3>
          <div className="flex-1 bg-slate-900/50 rounded-xl border border-dashed border-slate-700 flex items-center justify-center relative group overflow-hidden">
            {originalImage ? (
              <img src={originalImage} alt="Source" className="max-w-full max-h-full object-contain" />
            ) : (
              <div className="text-center p-6">
                <p className="text-4xl mb-4">🖼️</p>
                <p className="text-slate-400">Click to upload or drag an image</p>
              </div>
            )}
            <input 
              type="file" 
              accept="image/*" 
              onChange={handleFileChange}
              className="absolute inset-0 opacity-0 cursor-pointer"
            />
          </div>
        </div>

        <div className="glass-panel rounded-2xl p-4 flex flex-col gap-4 overflow-hidden">
          <h3 className="text-sm font-semibold uppercase tracking-wider text-slate-500">Preview Result</h3>
          <div className="flex-1 bg-slate-900/50 rounded-xl border border-slate-800 flex items-center justify-center">
            {isProcessing ? (
              <div className="flex flex-col items-center gap-4">
                <div className="w-12 h-12 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
                <p className="text-indigo-400 font-medium">Processing your vision...</p>
              </div>
            ) : editedImage ? (
              <img src={editedImage} alt="Edited Result" className="max-w-full max-h-full object-contain" />
            ) : (
              <p className="text-slate-600">Enter a prompt and click "Apply Edit"</p>
            )}
          </div>
        </div>
      </div>

      <div className="bg-slate-900 p-4 rounded-2xl border border-slate-800 flex flex-col md:flex-row gap-4">
        <input 
          type="text" 
          value={prompt}
          onChange={(e) => setPrompt(e.target.value)}
          placeholder="e.g., 'Add a retro 80s filter', 'Make the background a beach', 'Remove the person'"
          className="flex-1 bg-slate-950 border border-slate-700 rounded-xl px-4 py-3 text-white focus:outline-none focus:border-indigo-500 transition-colors"
        />
        <button 
          onClick={handleEdit}
          disabled={!originalImage || !prompt || isProcessing}
          className="bg-indigo-600 hover:bg-indigo-500 disabled:opacity-50 disabled:cursor-not-allowed text-white px-8 py-3 rounded-xl font-bold transition-all shadow-lg active:scale-95 whitespace-nowrap"
        >
          Apply Edit
        </button>
      </div>
    </div>
  );
};

export default ImageEditorView;

import React, { useState } from 'react';
import { GoogleGenAI } from "@google/genai";
import { VideoGenerationState } from '../types';

const VideoGeneratorView: React.FC = () => {
  const [sourceImage, setSourceImage] = useState<string | null>(null);
  const [prompt, setPrompt] = useState('');
  const [aspectRatio, setAspectRatio] = useState<'16:9' | '9:16'>('16:9');
  const [genState, setGenState] = useState<VideoGenerationState>({ status: 'idle' });

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (ev) => setSourceImage(ev.target?.result as string);
      reader.readAsDataURL(file);
    }
  };

  const generateVideo = async () => {
    // 1. Mandatory API Key selection for Veo
    // @ts-ignore
    if (!(await window.aistudio.hasSelectedApiKey())) {
      // @ts-ignore
      await window.aistudio.openSelectKey();
    }

    setGenState({ status: 'loading', message: 'Initiating Veo generation...' });

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const base64Data = sourceImage ? sourceImage.split(',')[1] : null;
      const mimeType = sourceImage ? sourceImage.split(',')[0].split(':')[1].split(';')[0] : null;

      let operation = await ai.models.generateVideos({
        model: 'veo-3.1-fast-generate-preview',
        prompt: prompt || 'Animate this photo with cinematic movement',
        ...(sourceImage ? {
          image: {
            imageBytes: base64Data!,
            mimeType: mimeType!
          }
        } : {}),
        config: {
          numberOfVideos: 1,
          resolution: '720p',
          aspectRatio
        }
      });

      // Status messages for better UX
      const statusMessages = [
        "Analyzing scene dynamics...",
        "Simulating fluid motions...",
        "Rendering textures and light...",
        "Polishing cinematic details...",
        "Finalizing high-quality MP4..."
      ];
      let msgIdx = 0;

      while (!operation.done) {
        setGenState({ 
          status: 'loading', 
          message: statusMessages[msgIdx % statusMessages.length] 
        });
        msgIdx++;
        await new Promise(resolve => setTimeout(resolve, 10000));
        operation = await ai.operations.getVideosOperation({ operation: operation });
      }

      const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
      const response = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
      const blob = await response.blob();
      const videoUrl = URL.createObjectURL(blob);

      setGenState({ status: 'completed', videoUrl });
    } catch (error: any) {
      console.error('Video gen error:', error);
      if (error.message?.includes("Requested entity was not found")) {
        // Reset key selection if it fails
        // @ts-ignore
        await window.aistudio.openSelectKey();
      }
      setGenState({ 
        status: 'error', 
        error: 'Generation failed. Please ensure you have a valid paid API key selected.' 
      });
    }
  };

  return (
    <div className="flex flex-col h-full gap-6">
      <header>
        <h2 className="text-2xl font-bold">Animate with Veo</h2>
        <p className="text-slate-400">Transform static photos into breathtaking videos with Veo 3.1.</p>
        <div className="mt-2 text-xs text-amber-400 bg-amber-900/20 px-3 py-1 rounded inline-block border border-amber-900/40">
          ⚠️ Requires selected API key from a paid project. 
          <a href="https://ai.google.dev/gemini-api/docs/billing" target="_blank" className="underline ml-1">Learn more</a>
        </div>
      </header>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
        <div className="space-y-4">
          <div className="glass-panel p-6 rounded-2xl flex flex-col gap-4">
            <h3 className="font-semibold">Step 1: Upload Frame</h3>
            <div className="aspect-video bg-slate-900/50 rounded-xl border-2 border-dashed border-slate-700 flex items-center justify-center relative hover:border-indigo-500 transition-colors cursor-pointer overflow-hidden">
              {sourceImage ? (
                <img src={sourceImage} className="w-full h-full object-contain" />
              ) : (
                <div className="text-center opacity-50">
                  <p className="text-4xl mb-2">📸</p>
