import React, { useState } from 'react';
import { GoogleGenAI } from "@google/genai";

const MapsGroundingView: React.FC = () => {
  const [query, setQuery] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [result, setResult] = useState<{ text: string, links: any[] } | null>(null);

  const handleSearch = async () => {
    if (!query.trim()) return;
    setIsLoading(true);
    setResult(null);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      // Get current location if possible
      let location = { latitude: 37.78193, longitude: -122.40476 }; // Default SF
      try {
        const pos = await new Promise<GeolocationPosition>((res, rej) => navigator.geolocation.getCurrentPosition(res, rej));
        location = { latitude: pos.coords.latitude, longitude: pos.coords.longitude };
      } catch (e) {
        console.warn("Location permission denied, using default.");
      }

      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-lite-latest",
        contents: query,
        config: {
          tools: [{ googleMaps: {} }, { googleSearch: {} }],
          toolConfig: {
            retrievalConfig: {
              latLng: location
            }
          }
        },
      });

      const text = response.text || "No detailed information found.";
      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
      const mapsLinks = chunks
        .filter((c: any) => c.maps)
        .map((c: any) => ({
          title: c.maps.title,
          uri: c.maps.uri
        }));

      setResult({ text, links: mapsLinks });
    } catch (error) {
      console.error('Maps error:', error);
      alert('Error fetching maps data.');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="flex flex-col h-full gap-6">
      <header>
        <h2 className="text-2xl font-bold">Smart Maps Grounding</h2>
        <p className="text-slate-400">Discover places and geography using real-time Google Maps data.</p>
      </header>

      <div className="glass-panel rounded-2xl p-2 flex border border-slate-800">
        <input 
          type="text" 
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          onKeyDown={(e) => e.key === 'Enter' && handleSearch()}
          placeholder="What are some good coffee shops nearby?"
          className="flex-1 bg-transparent border-none focus:ring-0 px-4 py-3"
        />
        <button 
          onClick={handleSearch}
          disabled={isLoading}
          className="bg-indigo-600 hover:bg-indigo-500 disabled:opacity-50 text-white px-8 py-3 rounded-xl font-bold transition-all"
        >
          {isLoading ? 'Searching...' : 'Explore'}
        </button>
      </div>

      <div className="flex-1 glass-panel rounded-2xl p-6 overflow-y-auto">
        {isLoading ? (
          <div className="h-full flex flex-col items-center justify-center gap-4">
            <div className="w-10 h-10 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
            <p className="text-slate-400">Fetching live location data...</p>
          </div>
