import React, { useState, useEffect } from 'react';

interface RpcNode {
  id: string;
  name: string;
  url: string;
  gateway: 'GOOGLE' | 'MICROSOFT' | 'XAI-NET' | 'CUSTOM';
  latency: number;
  status: 'ONLINE' | 'OFFLINE' | 'SYNCING';
  version: string;
  isUserOwned?: boolean;
  isPrimary?: boolean;
}

interface RpcEndpointsViewProps {
  onBack: () => void;
}

