  { id: '2', name: 'G-Cloud Gateway', url: 'https://gemini-rpc.google.internal', gateway: 'GOOGLE', latency: 45, status: 'ONLINE', version: 'v3.1', isUserOwned: false },
  { id: '3', name: 'Azure Secure Link', url: 'https://m-soft-node.azure.com/rpc', gateway: 'MICROSOFT', latency: 68, status: 'ONLINE', version: 'v1.9', isUserOwned: false },
];

