    const interval = setInterval(() => {
      setNodes(prev => prev.map(node => ({
        ...node,
        latency: node.status === 'ONLINE' ? Math.max(5, Math.floor(node.latency + (Math.random() * 4 - 2))) : 0
      })));
    }, 5000);
    return () => clearInterval(interval);
  }, []);

  const addNode = () => {
    if (!newNode.name || !newNode.url) return;
    const node: RpcNode = {
      id: Date.now().toString(),
      name: newNode.name.toUpperCase(),
      url: newNode.url.toLowerCase(),
      gateway: newNode.gateway as any,
      latency: 0,
      status: 'SYNCING',
      version: 'USER-NODE',
      isUserOwned: true,
      isPrimary: nodes.filter(n => n.isUserOwned).length === 0 // Make first own node primary by default
