        <div className="flex items-center justify-between">
          <div className="flex items-center gap-4">
            <button 
              onClick={onBack}
              className="text-2xl radium-text hover:scale-125 transition-all font-black px-2 py-1 bg-black/40 border border-[#39ff14]/10 rounded-lg" 
              title="RETURN TO SYSTEM"
            >
              &lt;&lt;
            </button>
            <h2 className="text-5xl font-black radium-text uppercase italic tracking-tighter">ENDPOINT HUB</h2>
          </div>
          <div className="flex gap-3">
             <div className="flex bg-black border border-slate-800 rounded-lg p-1 shadow-[0_0_15px_rgba(57,255,20,0.1)]">
                <button 
                  onClick={() => setFilter('ALL')}
                  className={`px-4 py-1.5 rounded-md text-[10px] font-black transition-all ${filter === 'ALL' ? 'bg-[#39ff14] text-black' : 'text-slate-500 hover:text-white'}`}
                >
                  ALL NODES
                </button>
                <button 
                  onClick={() => setFilter('OWN')}
                  className={`px-4 py-1.5 rounded-md text-[10px] font-black transition-all ${filter === 'OWN' ? 'bg-[#39ff14] text-black' : 'text-slate-500 hover:text-white'}`}
                >
                  MY OWN
                </button>
             </div>
             <button 
               onClick={() => setIsAdding(!isAdding)}
               className={`px-6 py-2 rounded-lg font-black text-[10px] uppercase tracking-widest transition-all border ${
                 isAdding ? 'bg-red-500/10 border-red-500 text-red-500' : 'bg-[#39ff14]/10 border-[#39ff14] text-[#39ff14] hover:bg-[#39ff14]/20'
               }`}
             >
