    setNewNode({ name: '', url: '', gateway: 'CUSTOM', apiKey: '' });
    setIsAdding(false);

    setTimeout(() => testNode(node), 1000);
  };

  const deleteNode = (id: string) => {
    setNodes(nodes.filter(n => n.id !== id));
  };

  const setPrimary = (id: string) => {
    setNodes(nodes.map(n => ({
      ...n,
      isPrimary: n.id === id
    })));
  };

