import React, { useState, useEffect } from 'react';

interface RpcNode {
  id: string;
  name: string;
  url: string;
  gateway: 'GOOGLE' | 'MICROSOFT' | 'XAI-NET' | 'CUSTOM' | 'TATUM';
  latency: number;
  status: 'ONLINE' | 'OFFLINE' | 'SYNCING';
  version: string;
  isUserOwned?: boolean;
  isPrimary?: boolean;
  apiKey?: string;
  blockCount?: number;
}

interface RpcEndpointsViewProps {
  onBack: () => void;
}

const DEFAULT_NODES: RpcNode[] = [
  { 
    id: 'tatum-core', 
    name: 'TATUM-GATEWAY-01', 
    url: 'https://migoxai-9160f6ed.gateway.tatum.io/', 
    gateway: 'TATUM', 
    apiKey: 't-6989e9664f6f4e3435d62281-0ac21b66ba86486489bbca7f',
    latency: 12, 
    status: 'ONLINE', 
    version: 'v4.0', 
    isUserOwned: true,
    isPrimary: true 
  },
  { id: '1', name: 'Primary Neural Node', url: 'https://rpc-quantum-01.migoxai.io', gateway: 'XAI-NET', latency: 12, status: 'ONLINE', version: 'v2.4', isUserOwned: false },
  { id: '2', name: 'G-Cloud Gateway', url: 'https://gemini-rpc.google.internal', gateway: 'GOOGLE', latency: 45, status: 'ONLINE', version: 'v3.1', isUserOwned: false },
];

const RpcEndpointsView: React.FC<RpcEndpointsViewProps> = ({ onBack }) => {
  const [nodes, setNodes] = useState<RpcNode[]>(() => {
    const saved = localStorage.getItem('migoxai_rpc_nodes');
    return saved ? JSON.parse(saved) : DEFAULT_NODES;
  });

  const [newNode, setNewNode] = useState({ name: '', url: '', gateway: 'CUSTOM', apiKey: '' });
  const [isAdding, setIsAdding] = useState(false);
  const [filter, setFilter] = useState<'ALL' | 'OWN'>('ALL');
  const [isDiagnosing, setIsDiagnosing] = useState<string | null>(null);

  useEffect(() => {
    localStorage.setItem('migoxai_rpc_nodes', JSON.stringify(nodes));
  }, [nodes]);

  const testNode = async (node: RpcNode) => {
    setIsDiagnosing(node.id);
    try {
      const response = await fetch(node.url, {
        method: 'POST',
        headers: {
          'accept': 'application/json',
          'content-type': 'application/json',
          'x-api-key': node.apiKey || '',
        },
        body: JSON.stringify({
          id: 1,
          jsonrpc: '2.0',
          method: 'getblockcount'
        })
      });

      if (response.ok) {
        const data = await response.json();
        setNodes(prev => prev.map(n => 
          n.id === node.id 
            ? { ...n, status: 'ONLINE', blockCount: data.result, latency: Math.floor(Math.random() * 20 + 10) } 
            : n
        ));
      } else {
        throw new Error('Connection failed');
      }
    } catch (err) {
      console.error('RPC Diagnostic Failed:', err);
      setNodes(prev => prev.map(n => n.id === node.id ? { ...n, status: 'OFFLINE' } : n));
    } finally {
      setIsDiagnosing(null);
    }
  };

  const addNode = () => {
    if (!newNode.name || !newNode.url) return;

    const node: RpcNode = {
      id: Date.now().toString(),
      name: newNode.name.toUpperCase(),
      url: newNode.url.toLowerCase(),
      gateway: newNode.gateway as any,
      apiKey: newNode.apiKey,
      latency: 0,
      status: 'SYNCING',
      version: 'USER-NODE',
      isUserOwned: true,
      isPrimary: nodes.filter(n => n.isUserOwned).length === 0 
    };

    setNodes(prev => [...prev, node]);
    setNewNode({ name: '', url: '', gateway: 'CUSTOM', apiKey: '' });
    setIsAdding(false);
    setTimeout(() => testNode(node), 1000);
  };

  const deleteNode = (id: string) => {
    setNodes(nodes.filter(n => n.id !== id));
  };

  const setPrimary = (id: string) => {
    setNodes(nodes.map(n => ({
      ...n,
      isPrimary: n.id === id
    })));
  };

  const filteredNodes = filter === 'OWN' ? nodes.filter(n => n.isUserOwned) : nodes;
  const primaryNode = nodes.find(n => n.isPrimary);

  return (
    <div className="flex flex-col h-full gap-8 animate-fade-in relative pb-12">
      <header className="flex flex-col gap-2 relative z-10">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-4">
            <button 
              onClick={onBack}
              className="text-2xl radium-text hover:scale-125 transition-all font-black px-2 py-1 bg-black/40 border border-[#39ff14]/10 rounded-lg" 
            >
              &lt;&lt;
            </button>
            <h2 className="text-5xl font-black radium-text uppercase italic tracking-tighter">RPC PARAMETERS</h2>
          </div>
          <div className="flex gap-3">
             <div className="flex bg-black border border-slate-800 rounded-lg p-1">
                <button 
                  onClick={() => setFilter('ALL')}
                  className={`px-4 py-1.5 rounded-md text-[10px] font-black transition-all ${filter === 'ALL' ? 'bg-[#39ff14] text-black' : 'text-slate-500 hover:text-white'}`}
                >
                  ALL NODES
                </button>
                <button 
                  onClick={() => setFilter('OWN')}
                  className={`px-4 py-1.5 rounded-md text-[10px] font-black transition-all ${filter === 'OWN' ? 'bg-[#39ff14] text-black' : 'text-slate-500 hover:text-white'}`}
                >
                  MY OWN
                </button>
             </div>
             <button 
               onClick={() => setIsAdding(!isAdding)}
               className={`px-6 py-2 rounded-lg font-black text-[10px] uppercase tracking-widest transition-all border ${
                 isAdding ? 'bg-red-500/10 border-red-500 text-red-500' : 'bg-[#39ff14]/10 border-[#39ff14] text-[#39ff14] hover:bg-[#39ff14]/20'
               }`}
             >
               {isAdding ? 'CANCEL' : '+ ADD RPC'}
             </button>
          </div>
        </div>
        <p className="text-slate-500 font-bold tracking-[0.4em] text-[10px] uppercase ml-16">Diagnostic Terminal // JSON-RPC 2.0 Interface</p>
      </header>

      <div className="flex flex-col gap-6 relative z-10 flex-1 min-h-0">
        {/* Main Backbone Focus */}
        <div className="glass-panel rounded-[2.5rem] p-10 border border-[#39ff14]/20 relative overflow-hidden radium-glow bg-gradient-to-br from-[#0f3d0e]/20 to-black group">
           <div className="absolute top-0 right-0 p-8 opacity-5">
             <span className="text-9xl mono font-black radium-text italic">LINK</span>
           </div>

           {primaryNode ? (
             <div className="relative z-10 h-full flex flex-col justify-between">
               <div>
                 <h3 className="text-[10px] font-black text-green-900 uppercase tracking-[0.4em] mb-6 flex items-center gap-2">
                   <span className="w-2 h-2 rounded-full bg-[#39ff14] animate-pulse"></span>
