                       <span className="bg-[#39ff14] text-black text-[9px] font-black px-3 py-1 rounded-md uppercase shadow-[0_0_15px_#39ff14]">ACTIVE</span>
                     </div>
                     <p className="text-sm text-slate-500 font-bold mono bg-black/40 inline-block px-4 py-2 rounded-xl border border-white/5 truncate max-w-xl">
                       {primaryNode.url}
                     </p>
                   </div>

                   <div className="flex gap-10 items-center bg-black/60 px-10 py-8 rounded-3xl border border-[#39ff14]/10 shadow-2xl backdrop-blur-xl">
                      <div className="text-center min-w-[100px]">
                        <p className="text-[10px] font-black text-slate-600 uppercase mb-2 tracking-widest">Latency</p>
                        <p className="text-3xl font-black radium-text mono">{primaryNode.latency}ms</p>
                      </div>
                      <div className="h-12 w-px bg-green-900/20"></div>
                      <div className="text-center min-w-[100px]">
                        <p className="text-[10px] font-black text-slate-600 uppercase mb-2 tracking-widest">Height</p>
                        <p className="text-3xl font-black text-white mono">{primaryNode.blockCount?.toLocaleString() || '---'}</p>
                      </div>
                   </div>
                 </div>
               </div>
             </div>
           ) : (
             <div className="h-40 flex items-center justify-center border border-dashed border-[#39ff14]/20 rounded-3xl">
                <p className="text-slate-600 font-black uppercase tracking-[0.5em]">No Primary Node Detected</p>
             </div>
           )}
        </div>

        {isAdding && (
          <div className="glass-panel rounded-[2rem] p-8 border border-[#39ff14]/40 radium-glow bg-black/90 animate-fade-in">
            <h3 className="text-[10px] font-black text-[#39ff14] uppercase tracking-[0.5em] mb-6">Initialize New Neural Link</h3>
            <div className="grid grid-cols-1 md:grid-cols-4 gap-6 items-end">
