                  onChange={e => setNewNode({...newNode, name: e.target.value})}
                  placeholder="X-NODE-01"
                  className="w-full bg-black border border-green-900/40 rounded-xl px-4 py-3 text-sm font-bold text-[#39ff14] focus:border-[#39ff14] outline-none"
                />
              </div>
              <div className="space-y-2">
                <label className="text-[9px] font-black text-slate-500 uppercase tracking-widest">Endpoint URL</label>
                <input 
                  type="text" 
                  value={newNode.url}
